BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=public,extensions;
SELECT plan(15);

-- Cancel→reorder: released_at releases a requirement claim; batch attempts
-- version re-confirms; the live-supplier unique ignores cancelled orders and
-- allows supplemental batches; DOC-02 renders as PDF.

SELECT has_column('public','order_requirement_lines','released_at',
    'order lines carry the claim-release timestamp');
SELECT has_column('public','order_allocation_batches','attempt',
    'allocation batches carry the retry attempt');

INSERT INTO tenancy_organizations(id,name,tax_id) VALUES
 ('88aa0000-0000-4000-8000-000000000001','Retry Org','R170-1');
INSERT INTO tenancy_memberships(org_id,user_id,role) VALUES
 ('88aa0000-0000-4000-8000-000000000001','88aa1000-0000-4000-8000-000000000001','WORKSHOP_MANAGER');
INSERT INTO projects(id,org_id,code,name,client_name,created_by) VALUES
 ('88aa2000-0000-4000-8000-000000000001','88aa0000-0000-4000-8000-000000000001','P-R170','Casa','Fixture','88aa1000-0000-4000-8000-000000000001');
INSERT INTO project_positions(id,org_id,project_id,position_index,typology,system_id,width_mm,height_mm,parametric_tree,bom_snapshot)
