INSERT INTO purchase_requirement_lines(id,requirement_key,projection_id,project_id,project_version_id,org_id,bom_hash,snapshot_sha256,order_type,category,technical_identity,purchasing_sku,physical_stock_identity,unit,quantity,specification,source_trace) VALUES
 ('88aa7000-0000-4000-8000-000000000001','2222222222222222222222222222222222222222222222222222222222222222','88aa6000-0000-4000-8000-000000000001','88aa2000-0000-4000-8000-000000000001','88aa5000-0000-4000-8000-000000000001','88aa0000-0000-4000-8000-000000000001','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb','SUPPLIER_GLASS_PO','GLASS','{}','GLASS-BUY',NULL,'EA',2,'{}','[]');
