INSERT INTO orders(id,org_id,project_id,order_type,order_code,status,supplier_name,payload_json,project_version_id,allocation_batch_id,supplier_eligibility_id,bom_hash,revision_snapshot_sha256,purchase_projection_hash,allocation_identity,order_snapshot_hash,supplier_identity,supplier_details,confirmed_by,confirmed_at) VALUES
 ('88ab1000-0000-4000-8000-000000000001','88aa0000-0000-4000-8000-000000000001','88aa2000-0000-4000-8000-000000000001','SUPPLIER_GLASS_PO','PO-170-1','DRAFT','Proveedor 1','{}','88aa5000-0000-4000-8000-000000000001','88ab0000-0000-4000-8000-000000000001','88aa8000-0000-4000-8000-000000000001','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb','1111111111111111111111111111111111111111111111111111111111111111','7777777777777777777777777777777777777777777777777777777777777777','8888888888888888888888888888888888888888888888888888888888888888','SUP-1','{}','88aa1000-0000-4000-8000-000000000001',now());
INSERT INTO order_requirement_lines(id,order_id,requirement_line_id,project_id,project_version_id,org_id,order_type,bom_hash,revision_snapshot_sha256,quantity,line_snapshot,line_hash) VALUES
 ('88ab2000-0000-4000-8000-000000000001','88ab1000-0000-4000-8000-000000000001','88aa7000-0000-4000-8000-000000000001','88aa2000-0000-4000-8000-000000000001','88aa5000-0000-4000-8000-000000000001','88aa0000-0000-4000-8000-000000000001','SUPPLIER_GLASS_PO','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb',2,'{}','9999999999999999999999999999999999999999999999999999999999999999');

-- A second live claim on the same requirement collides.
SELECT lives_ok($$INSERT INTO order_allocation_batches(id,project_id,project_version_id,org_id,bom_hash,snapshot_sha256,order_type,allocation_hash,confirmed_by,confirmed_at,attempt)
 VALUES('88ab0000-0000-4000-8000-000000000002','88aa2000-0000-4000-8000-000000000001','88aa5000-0000-4000-8000-000000000001','88aa0000-0000-4000-8000-000000000001','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb','SUPPLIER_GLASS_PO','5656565656565656565656565656565656565656565656565656565656565656','88aa1000-0000-4000-8000-000000000001',now(),2)$$,'a retry batch exists as attempt 2 of the same version+type');
SELECT lives_ok($$INSERT INTO orders(id,org_id,project_id,order_type,order_code,status,supplier_name,payload_json,project_version_id,allocation_batch_id,supplier_eligibility_id,bom_hash,revision_snapshot_sha256,purchase_projection_hash,allocation_identity,order_snapshot_hash,supplier_identity,supplier_details,confirmed_by,confirmed_at)
 VALUES('88ab1000-0000-4000-8000-000000000002','88aa0000-0000-4000-8000-000000000001','88aa2000-0000-4000-8000-000000000001','SUPPLIER_GLASS_PO','PO-170-2','DRAFT','Proveedor 1','{}','88aa5000-0000-4000-8000-000000000001','88ab0000-0000-4000-8000-000000000002','88aa8000-0000-4000-8000-000000000001','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb','1111111111111111111111111111111111111111111111111111111111111111','7777777777777777777777777777777777777777777777777777777777777778','8888888888888888888888888888888888888888888888888888888888888889','SUP-1','{}','88aa1000-0000-4000-8000-000000000001',now())$$,'a supplemental live order to the same supplier binds a different batch');
SELECT throws_ok($$INSERT INTO orders(id,org_id,project_id,order_type,order_code,status,supplier_name,payload_json,project_version_id,allocation_batch_id,supplier_eligibility_id,bom_hash,revision_snapshot_sha256,purchase_projection_hash,allocation_identity,order_snapshot_hash,supplier_identity,supplier_details,confirmed_by,confirmed_at)
 VALUES('88ab1000-0000-4000-8000-000000000003','88aa0000-0000-4000-8000-000000000001','88aa2000-0000-4000-8000-000000000001','SUPPLIER_GLASS_PO','PO-170-3','DRAFT','Proveedor 1','{}','88aa5000-0000-4000-8000-000000000001','88ab0000-0000-4000-8000-000000000001','88aa8000-0000-4000-8000-000000000001','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb','1111111111111111111111111111111111111111111111111111111111111112','7777777777777777777777777777777777777777777777777777777777777779','8888888888888888888888888888888888888888888888888888888888888890','SUP-1','{}','88aa1000-0000-4000-8000-000000000001',now())$$,'23505',NULL,'a second live order to the same supplier in the same batch collides');
SELECT throws_ok($$INSERT INTO order_requirement_lines(order_id,requirement_line_id,project_id,project_version_id,org_id,order_type,bom_hash,revision_snapshot_sha256,quantity,line_snapshot,line_hash)
 VALUES('88ab1000-0000-4000-8000-000000000002','88aa7000-0000-4000-8000-000000000001','88aa2000-0000-4000-8000-000000000001','88aa5000-0000-4000-8000-000000000001','88aa0000-0000-4000-8000-000000000001','SUPPLIER_GLASS_PO','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb',2,'{}','9898989898989898989898989898989898989898989898989898989898989898')$$,'23505',NULL,'a requirement line cannot be claimed by two live orders');
SELECT throws_ok($$INSERT INTO order_allocation_batches(project_id,project_version_id,org_id,bom_hash,snapshot_sha256,order_type,allocation_hash,confirmed_by,confirmed_at,attempt)
 VALUES('88aa2000-0000-4000-8000-000000000001','88aa5000-0000-4000-8000-000000000001','88aa0000-0000-4000-8000-000000000001','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb','SUPPLIER_GLASS_PO','5757575757575757575757575757575757575757575757575757575757575757','88aa1000-0000-4000-8000-000000000001',now(),2)$$,'23505',NULL,'a duplicate attempt for the same version+type is rejected');

-- Evidence stays immutable; only the released_at stamp is allowed.
SELECT throws_ok($$UPDATE order_requirement_lines SET quantity=9 WHERE id='88ab2000-0000-4000-8000-000000000001'$$,'42501','documentary_evidence_immutable','evidence columns cannot be edited');
SELECT throws_ok($$DELETE FROM order_requirement_lines WHERE id='88ab2000-0000-4000-8000-000000000001'$$,'42501','documentary_evidence_immutable','order lines cannot be deleted');

-- Cancel the order, release the claim, re-order through attempt 2.
SELECT lives_ok($$UPDATE orders SET status='CANCELLED',cancelled_by='88aa1000-0000-4000-8000-000000000001',cancelled_at=now(),updated_at=now() WHERE id='88ab1000-0000-4000-8000-000000000001'$$,'the draft order cancels with operator evidence');
SELECT lives_ok($$UPDATE order_requirement_lines SET released_at=now() WHERE id='88ab2000-0000-4000-8000-000000000001'$$,'cancellation stamps released_at on the claimed line');
SELECT throws_ok($$UPDATE order_requirement_lines SET released_at=NULL WHERE id='88ab2000-0000-4000-8000-000000000001'$$,'42501','documentary_evidence_immutable','a released claim cannot be un-released');
SELECT lives_ok($$INSERT INTO orders(id,org_id,project_id,order_type,order_code,status,supplier_name,payload_json,project_version_id,allocation_batch_id,supplier_eligibility_id,bom_hash,revision_snapshot_sha256,purchase_projection_hash,allocation_identity,order_snapshot_hash,supplier_identity,supplier_details,confirmed_by,confirmed_at)
 VALUES('88ab1000-0000-4000-8000-000000000004','88aa0000-0000-4000-8000-000000000001','88aa2000-0000-4000-8000-000000000001','SUPPLIER_GLASS_PO','PO-170-4','DRAFT','Proveedor 1','{}','88aa5000-0000-4000-8000-000000000001','88ab0000-0000-4000-8000-000000000001','88aa8000-0000-4000-8000-000000000001','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb','1111111111111111111111111111111111111111111111111111111111111113','7777777777777777777777777777777777777777777777777777777777777780','8888888888888888888888888888888888888888888888888888888888888891','SUP-1','{}','88aa1000-0000-4000-8000-000000000001',now())$$,'a cancelled order does not block re-ordering the same supplier in its batch');
SELECT lives_ok($$INSERT INTO order_requirement_lines(order_id,requirement_line_id,project_id,project_version_id,org_id,order_type,bom_hash,revision_snapshot_sha256,quantity,line_snapshot,line_hash)
 VALUES('88ab1000-0000-4000-8000-000000000002','88aa7000-0000-4000-8000-000000000001','88aa2000-0000-4000-8000-000000000001','88aa5000-0000-4000-8000-000000000001','88aa0000-0000-4000-8000-000000000001','SUPPLIER_GLASS_PO','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb',2,'{}','9898989898989898989898989898989898989898989898989898989898989898')$$,'the released requirement claims into the retry order');

-- DOC-02 renders as PDF: check1 binds it to glass orders — the supplemental
-- live glass order takes the artifact slot.
SELECT lives_ok($$INSERT INTO document_artifacts(id,org_id,project_id,project_version_id,artifact_scope,artifact_scope_id,document_type,format,order_id,order_type,bom_hash,revision_snapshot_sha256,storage_bucket,storage_object_key,file_sha256,media_type,byte_size,created_by)
 VALUES('88ab3000-0000-4000-8000-000000000001','88aa0000-0000-4000-8000-000000000001','88aa2000-0000-4000-8000-000000000001','88aa5000-0000-4000-8000-000000000001','ORDER','88ab1000-0000-4000-8000-000000000002','DOC-02','PDF','88ab1000-0000-4000-8000-000000000002','SUPPLIER_GLASS_PO','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb','documents','org_88aa0000-0000-4000-8000-000000000001/projects/88aa2000-0000-4000-8000-000000000001/REV-A/doc02.pdf','6161616161616161616161616161616161616161616161616161616161616161','application/pdf',1024,'88aa1000-0000-4000-8000-000000000001')$$,'DOC-02 binds the glass order slot as PDF');

SELECT finish();
ROLLBACK;
